#include <HBEngine/SceneRender.hpp>
#include <nlohmann/json.hpp>
#include <fstream>
#include <iostream>
using namespace hb::gpu;
static int display(float v){v=std::clamp(v,0.f,1.f);return int(std::round(255*(v<=.0031308f?v*12.92f:1.055f*std::pow(v,1/2.4f)-.055f)));}
int main(int argc,char** argv){try{
 if(argc!=2){throw std::runtime_error("fixture path");}std::ifstream input(argv[1]);const auto cases=nlohmann::json::parse(input);Device gpu;SceneRenderer r(gpu,64,16);SceneFrame frame;frame.eye={0,0,10,1};frame.ambient={0,0,0,1};r.setLights({});r.begin(frame);
 std::vector<SceneRenderer::Probe> captures;captures.reserve(4);const auto capture=[&](auto& p,std::array<float,4> color){for(UINT f=0;f<6;f++){r.beginProbe(p,f,identity,{0,0,0,1},color);r.endProbe();}r.filterProbe(p);};for(int i=0;i<4;i++){captures.push_back(r.createProbe(16));std::array<float,4> color{0,0,0,1};color[i%3]=1;capture(captures.back(),color);}
 auto mesh=r.createMesh({{{-1,-1,.5f}},{{1,-1,.5f}},{{1,1,.5f}},{{-1,1,.5f}}},{0,1,2,0,2,3});SceneMaterial material;material.unlit=true;material.toneMapped=false;auto debug=r.createProgram("StructuredBuffer<float> queryValues:register(t7);","float3 sphereAt=float3(queryValues[0],queryValues[1],queryValues[2]),sphereRay=float3(queryValues[3],queryValues[4],queryValues[5]);base.rgb=hbBuiltinNormalUnit(probeDirection(probeSettings[0],sphereAt,sphereRay),float3(0,0,0))*.5+.5;base.a=probeWeight(probeSettings[0],sphereAt);",{0,0,0,0,0,1});
 int samples=0,maxError=0;for(const auto& c:cases)for(bool projection:{false,true}){
  ProbeSettings p;setProbeSphereVolume(p,c.at("center").get<std::array<float,3>>(),c.at("radius").get<float>(),projection);const auto center=c.at("capture").get<std::array<float,3>>();p.center={center[0],center[1],center[2],1};p.minimum[3]=c.at("blend").get<float>();const auto point=c.at("point").get<std::vector<float>>(),ray=c.at("ray").get<std::vector<float>>();auto values=point;values.insert(values.end(),ray.begin(),ray.end());r.setProgramParameters(debug,values);std::array<SceneRenderer::ProbeBinding,2> direct{};direct[0]={&captures[0],p};r.begin(frame);r.draw(mesh,identity,identity,material,{},{},0,0,&debug,{},{},nullptr,nullptr,nullptr,&direct,nullptr,0,nullptr,false);const auto pixels=r.readPixels();auto expected=c.at("expected").get<std::array<double,4>>();if(!projection){const double length=std::hypot(double(ray[0]),double(ray[1]),double(ray[2]));for(unsigned k=0;k<3;k++)expected[k]=length?ray[k]/length:0;}
  for(unsigned k=0;k<4;k++){const int actual=pixels[(8*64+32)*4+k],reference=k==3?int(std::round(std::clamp(expected[k],0.,1.)*255)):display(float(expected[k]*.5+.5)),error=std::abs(actual-reference);maxError=std::max(maxError,error);if(error>2)throw std::runtime_error(nlohmann::json({{"case",c},{"projection",projection},{"channel",k},{"actual",actual},{"reference",reference}}).dump());}samples++;
 }
 material.unlit=false;material.metalness=1;material.roughness=.3f;std::vector<SceneRenderer::ProbeBinding> bindings;for(unsigned i=0;i<4;i++){ProbeSettings p;setProbeSphereVolume(p,{-.75f+i*.5f,0,.5f},.22f);p.center={-.75f+i*.5f,0,.5f,1};p.minimum[3]=0;bindings.push_back({&captures[i],p});}r.setGlobalProbes(bindings);
 const auto draw=[&](bool global,const std::array<SceneRenderer::ProbeBinding,2>* direct=nullptr){r.begin(frame);r.draw(mesh,identity,identity,material,{},{},0,0,nullptr,{},{},nullptr,nullptr,nullptr,direct,nullptr,0,nullptr,global);return r.readPixels();};const auto all=draw(true);for(unsigned i=0;i<4;i++){std::array<SceneRenderer::ProbeBinding,2> direct{};direct[0]=bindings[i];const auto reference=draw(false,&direct);for(unsigned k=0;k<3;k++)if(std::abs(int(all[(8*64+8+i*16)*4+k])-int(reference[(8*64+8+i*16)*4+k]))>2)throw std::runtime_error("sphere atlas/direct room mismatch");}
 for(unsigned k=0;k<3;k++){if(all[(6*64+14)*4+k]>2)throw std::runtime_error("sphere AABB corner included");}const auto copies=r.probeAtlasCopies(),layouts=r.probeAtlasLayoutBuilds();bindings[3].settings.center[3]=.5f;r.setGlobalProbes(bindings);draw(true);if(r.probeAtlasCopies()!=copies||r.probeAtlasLayoutBuilds()!=layouts||!r.probeAtlasMetadataFastUpdates())throw std::runtime_error("sphere intensity recaptured/repacked");
 const auto beforeRank=draw(true);std::reverse(bindings.begin(),bindings.end());r.setGlobalProbes(bindings);const auto afterRank=draw(true);for(std::size_t i=0;i<beforeRank.size();i++)if(std::abs(int(beforeRank[i])-int(afterRank[i]))>2)throw std::runtime_error("sphere rank changed disjoint image");if(r.probeAtlasCopies()!=copies)throw std::runtime_error("rank order recopied same captures");
 auto invalid=bindings;invalid[0].settings.localX[0]=2;bool rejected=false;try{r.setGlobalProbes(invalid);}catch(const std::exception&){rejected=true;}if(!rejected)throw std::runtime_error("stretched sphere accepted");r.setGlobalProbes({});r.releaseProbes();if(r.probeAtlasCPUBytes()||r.probeAtlasBytes())throw std::runtime_error("sphere retained");
 std::cout<<nlohmann::json({{"passed",true},{"samples",samples},{"maxErrorBytes",maxError},{"toleranceBytes",2},{"globalRooms",4},{"cornerExcluded",true},{"rankSourceSlotsRetained",true},{"intensityMetadataOnly",true},{"nonUnitSphereRejected",true},{"released",true},{"scope","Actual D3D11 production probeWeight/probeDirection via direct bindings, independent world-sphere quadratic/color+alpha reference, projection on/off and zero/tiny/huge rays. Four real HDR sphere captures in global atlas versus direct physical reference, AABB corner rejection, settings-only reuse and release."}}).dump();
}catch(const std::exception& e){std::cerr<<e.what();return 1;}}
